"use client";

import { useState } from "react";
import {
    Plus,
    Search,
    Filter,
    MoreVertical,
    Edit2,
    Trash2,
    Eye,
    Pill,
    AlertCircle,
    Loader2,
    X,
    Package
} from "lucide-react";
import { useData } from "@/lib/hooks";

export default function ProductsPage() {
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedCategory, setSelectedCategory] = useState("All");
    const [showAddModal, setShowAddModal] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState<any>(null);

    const { data: products, loading, error, refetch } = useData<any[]>("/api/products");

    const categories = ["All", "Pain Relief", "Antibiotics", "Diabetes", "Cardiology", "Vitamins", "Others"];

    const filteredProducts = products?.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.brand.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = selectedCategory === "All" || p.category === selectedCategory;
        return matchesSearch && matchesCategory;
    }) || [];

    const handleAddProduct = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            const formData = new FormData(e.currentTarget);
            const productData = Object.fromEntries(formData.entries());

            console.log("Submitting product data:", productData);

            const res = await fetch("/api/products", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(productData)
            });

            if (res.ok) {
                setShowAddModal(false);
                refetch();
            } else {
                const errorData = await res.json();
                console.error("Server error:", errorData);
                alert("Error: " + (errorData.details || errorData.error || "Failed to save product"));
            }
        } catch (err: any) {
            console.error("Submission error:", err);
            alert("Submission failed: " + err.message);
        } finally {
            setIsSubmitting(false);
        }
    };

    if (loading) return (
        <div className="flex h-[60vh] items-center justify-center">
            <Loader2 className="h-10 w-10 text-purple-600 animate-spin" />
        </div>
    );

    return (
        <>
            <div className="flex flex-col gap-8 animate-fade-in-up">
                {/* Page Header */}
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight">IR Inventory</h1>
                        <p className="text-gray-500 mt-1 font-medium">Manage IR SOFTWARE products and stock levels.</p>
                    </div>
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="btn-primary flex items-center gap-2"
                    >
                        <Plus className="h-4 w-4" />
                        Add New Product
                    </button>
                </div>

                {/* Filters Section */}
                <div className="flex flex-col md:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Search by name, brand orSalt..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="h-12 w-full rounded-xl border border-gray-200 bg-white pl-12 pr-4 text-sm focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 transition-all shadow-sm"
                        />
                    </div>
                    <div className="flex items-center gap-2 overflow-x-auto pb-2 md:pb-0">
                        {categories.map((cat) => (
                            <button
                                key={cat}
                                onClick={() => setSelectedCategory(cat)}
                                className={`px-4 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-all ${selectedCategory === cat
                                    ? "bg-purple-600 text-white shadow-lg shadow-purple-500/30"
                                    : "bg-white text-gray-600 border border-gray-200 hover:border-purple-500"
                                    }`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Products Grid */}
                <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                    {filteredProducts.map((product) => (
                        <div key={product.id} className="card-premium rounded-2xl overflow-hidden group hover:scale-[1.02] transition-transform">
                            <div className="p-6">
                                <div className="flex items-start justify-between mb-4">
                                    <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-100 to-blue-100 flex items-center justify-center">
                                        <Package className="h-6 w-6 text-purple-600" />
                                    </div>
                                    <button
                                        onClick={() => setSelectedProduct(product)}
                                        className="p-2 hover:bg-gray-100 rounded-lg text-gray-400 transition-colors"
                                    >
                                        <Eye className="h-5 w-5" />
                                    </button>
                                </div>

                                <h3 className="font-bold text-gray-900 text-lg lg:text-base group-hover:text-purple-600 transition-colors truncate">
                                    {product.name}
                                </h3>
                                <p className="text-sm text-gray-500 mb-4">{product.brand}</p>

                                <div className="grid grid-cols-2 gap-4 mb-4">
                                    <div className="p-3 rounded-xl bg-purple-50">
                                        <p className="text-[10px] text-purple-500 uppercase font-black">Strip Price</p>
                                        <p className="text-lg font-black text-purple-600">PKR {product.salePrice}</p>
                                    </div>
                                    <div className="p-3 rounded-xl bg-blue-50">
                                        <p className="text-[10px] text-blue-500 uppercase font-black">Unit/Tablet</p>
                                        <p className="text-lg font-black text-blue-600">PKR {(product.salePrice / (product.unitsPerPack || 1)).toFixed(2)}</p>
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4 mb-6">
                                    <div className="p-3 rounded-xl bg-gray-50">
                                        <p className="text-[10px] text-gray-500 uppercase font-bold">Stock (Total Units)</p>
                                        <p className={`text-lg font-bold ${product.stock < 10 ? 'text-red-500' : 'text-gray-900'}`}>{product.stock}</p>
                                    </div>
                                    <div className="p-3 rounded-xl bg-gray-50">
                                        <p className="text-[10px] text-gray-500 uppercase font-bold">Tablets/Strip</p>
                                        <p className="text-lg font-bold text-gray-600 font-mono">{product.unitsPerPack || 1}</p>
                                    </div>
                                </div>

                                <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                                    <div className="flex -space-x-2">
                                        {product.batches?.map((b: any, i: number) => (
                                            <div key={b.id} className="w-8 h-8 rounded-full border-2 border-white bg-gray-200 flex items-center justify-center text-[10px] font-bold" title={`Expiry: ${new Date(b.expiryDate).toLocaleDateString()}`}>
                                                B{i + 1}
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="badge badge-info text-[10px]">{product.category}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

            </div>

            <Modals
                showAddModal={showAddModal}
                setShowAddModal={setShowAddModal}
                handleAddProduct={handleAddProduct}
                isSubmitting={isSubmitting}
                selectedProduct={selectedProduct}
                setSelectedProduct={setSelectedProduct}
                categories={categories}
            />
        </>
    );
}

function Modals({
    showAddModal,
    setShowAddModal,
    handleAddProduct,
    isSubmitting,
    selectedProduct,
    setSelectedProduct,
    categories
}: any) {
    return (
        <>
            {/* Add Product Modal */}
            {showAddModal && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4 overflow-y-auto">
                    <div className="bg-white rounded-3xl w-full max-w-2xl max-h-[90vh] overflow-y-auto animate-fade-in-up shadow-2xl">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                            <h2 className="text-xl font-bold text-gray-900">Add New Product</h2>
                            <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-gray-100 rounded-full">
                                <Plus className="h-5 w-5 rotate-45" />
                            </button>
                        </div>
                        <form onSubmit={handleAddProduct} className="p-6">
                            <div className="grid md:grid-cols-2 gap-6">
                                <div className="space-y-4">
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Name</label>
                                        <input name="name" required type="text" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Brand</label>
                                        <input name="brand" required type="text" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Category</label>
                                        <select name="category" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20">
                                            {categories.filter((c: string) => c !== "All").map((c: string) => <option key={c} value={c}>{c}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Tablets per Strip</label>
                                        <input name="unitsPerPack" required type="number" defaultValue={1} min={1} className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="text-sm font-medium text-gray-700">Purchase PKR</label>
                                            <input name="purchasePrice" required type="number" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                        </div>
                                        <div>
                                            <label className="text-sm font-medium text-gray-700">Strip Price PKR</label>
                                            <input name="salePrice" required type="number" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Default Discount (PKR)</label>
                                        <input name="defaultDiscount" required type="number" defaultValue={0} className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                </div>
                                <div className="space-y-4">
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Initial Batch No</label>
                                        <input name="batchNo" required type="text" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Expiry Date</label>
                                        <input name="expiryDate" required type="date" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                    <div>
                                        <label className="text-sm font-medium text-gray-700">Qty</label>
                                        <input name="quantity" required type="number" className="w-full mt-1 h-11 rounded-xl border-gray-200 bg-gray-50 px-4 text-sm focus:ring-2 focus:ring-purple-500/20" />
                                    </div>
                                </div>
                            </div>
                            <div className="flex gap-4 mt-8">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 rounded-xl border border-gray-200 font-medium">Cancel</button>
                                <button disabled={isSubmitting} type="submit" className="flex-1 py-3 rounded-xl bg-purple-600 text-white font-medium shadow-lg shadow-purple-500/30">
                                    {isSubmitting ? "Saving..." : "Save Product"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Product Details Modal */}
            {selectedProduct && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4 overflow-y-auto">
                    <div className="bg-white rounded-3xl w-full max-w-3xl max-h-[90vh] overflow-y-auto animate-fade-in-up shadow-2xl">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                            <h2 className="text-xl font-bold text-gray-900">Product Details</h2>
                            <button onClick={() => setSelectedProduct(null)} className="p-2 hover:bg-gray-100 rounded-full">
                                <X className="h-5 w-5" />
                            </button>
                        </div>
                        <div className="p-6">
                            <div className="flex items-center gap-6 mb-8">
                                <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-purple-500 to-blue-500 flex items-center justify-center">
                                    <Package className="h-10 w-10 text-white" />
                                </div>
                                <div className="flex-1">
                                    <h2 className="text-2xl font-bold text-gray-900">{selectedProduct.name}</h2>
                                    <p className="text-gray-500 font-medium">{selectedProduct.brand}</p>
                                    <div className="flex flex-wrap gap-2 mt-2">
                                        <span className="badge badge-info">{selectedProduct.category}</span>
                                        <span className={`badge ${selectedProduct.stock > 20 ? 'badge-success' : 'badge-danger'}`}>
                                            {selectedProduct.stock} units in stock
                                        </span>
                                        <span className="badge bg-purple-100 text-purple-700 font-bold border border-purple-200">
                                            Strip: PKR {selectedProduct.salePrice}
                                        </span>
                                        <span className="badge bg-blue-100 text-blue-700 font-bold border border-blue-200">
                                            Tablet: PKR {(selectedProduct.salePrice / (selectedProduct.unitsPerPack || 1)).toFixed(2)}
                                        </span>
                                    </div>
                                </div>
                            </div>

                            <h3 className="font-bold text-gray-900 mb-4">Batch History</h3>
                            <div className="bg-gray-50 rounded-2xl overflow-hidden">
                                <table className="w-full">
                                    <thead>
                                        <tr className="border-b border-gray-200">
                                            <th className="text-left py-4 px-6 text-sm font-bold text-gray-600">Batch No</th>
                                            <th className="text-left py-4 px-6 text-sm font-bold text-gray-600">Expiry</th>
                                            <th className="text-left py-4 px-6 text-sm font-bold text-gray-600">Current Qty</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {selectedProduct.batches?.map((b: any) => (
                                            <tr key={b.id} className="border-b border-gray-100 last:border-0">
                                                <td className="py-4 px-6 font-medium text-gray-900">{b.batchNo}</td>
                                                <td className="py-4 px-6 text-gray-600">{new Date(b.expiryDate).toLocaleDateString()}</td>
                                                <td className="py-4 px-6 font-bold text-purple-600">{b.quantity}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}
